/** A stale prepared attempt must not authorize a dictionary committed after its native capture. */
class LmdbPreparedForeignSnapshotRaceTest {
	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI S = VF.createIRI("urn:prepared-foreign:subject");
	private static final IRI P = VF.createIRI("urn:prepared-foreign:predicate");
	private static final IRI O = VF.createIRI("urn:prepared-foreign:object");
	private static final IRI SECOND = VF.createIRI("urn:prepared-foreign:second");
	private static final List<Retained> RETAINED = new CopyOnWriteArrayList<>();

	private record Retained(Path directory, Lock directoryLock, ExecutorService reader, Future<?> task, Process child) {
	}

	@Test
	void foreignDictionaryCommitAfterSealedCaptureCannotAdmitItsOldSnapshot(
			@TempDir(cleanup = CleanupMode.NEVER) Path evidence) throws Exception {
		Path directory = evidence.resolve("store");
		LmdbStoreConfig config = config();
		write(directory, config, false);
		Path seal = directory.resolve(PreparedBulkStore.FILE_NAME);
		Path originalSeal = evidence.resolve("first-prepared-seal.bin");
		assertTrue(Files.isRegularFile(seal), "setup must publish a first real prepared seal");
		Files.copy(seal, originalSeal);

		write(directory, config, true);
		Path currentSeal = evidence.resolve("second-prepared-seal.bin");
		assertTrue(Files.isRegularFile(seal), "setup must publish a second real prepared seal");
		Files.copy(seal, currentSeal);
		assertFalseBytesEqual(Files.readAllBytes(originalSeal), Files.readAllBytes(currentSeal));
		Files.copy(originalSeal, seal, StandardCopyOption.REPLACE_EXISTING);

		StoreProperties control = new StoreProperties(directory.toFile());
		assertTrue(control.load());
		assertNotNull(RdfTermDomainQualification.decode(control.getRdfTermDomainQualification()),
				"setup must retain a real current domain witness");
		assertNull(PreparedBulkStore.readSealed(directory, control, config),
				"the retained first seal must not match the current native pair");
		assertNotNull(PreparedBulkStore.readCurrent(directory, control, config),
				"the current native pair must independently admit before the injected write");

		long beforeTransaction = LmdbCompatibilityFixtures.nativeTransactionId(directory);
		byte[] oldGeneration = LmdbCompatibilityFixtures.nativeGet(directory, "gc_meta",
				ReferenceCountProof.GENERATION_KEY);
		assertNotNull(oldGeneration);
		assertTrue(oldGeneration.length == ReferenceCountProof.GENERATION_BYTES);
		byte[] replacement = oldGeneration.clone();
		replacement[0] ^= 1;
		Files.write(evidence.resolve("generation-before.bin"), oldGeneration);
		Files.write(evidence.resolve("generation-after.bin"), replacement);

		Gate gate = new Gate(directory.toFile());
		assertTrue(gate.load());
		ExecutorService reader = Executors.newSingleThreadExecutor(Thread.ofPlatform().daemon().factory());
		Lock directoryLock;
		try {
			directoryLock = new DirectoryLockManager(directory.toFile()).lockOrFail();
		} catch (Throwable failure) {
			reader.shutdown();
			throw failure;
		}
		AtomicReference<Future<PreparedBulkStore.Snapshot>> task = new AtomicReference<>();
		AtomicReference<Process> child = new AtomicReference<>();
		AtomicBoolean childSettled = new AtomicBoolean(true);
		try (AutoCloseable cleanup = () -> {
			gate.release.countDown();
			reader.shutdown();
			Process process = child.get();
			boolean readerSettled;
			try {
				readerSettled = reader.awaitTermination(30, TimeUnit.SECONDS);
			} catch (InterruptedException interrupted) {
				RETAINED.add(new Retained(directory, directoryLock, reader, task.get(), process));
				Thread.currentThread().interrupt();
				throw interrupted;
			}
			if (!readerSettled || !childSettled.get() || process != null && process.isAlive()) {
				RETAINED.add(new Retained(directory, directoryLock, reader, task.get(), process));
				System.err.println("Retained unsettled prepared-preflight owner; fixture=" + evidence
						+ " childPid=" + (process == null ? "none" : process.pid()));
				throw new IllegalStateException("Prepared-preflight owner remained live; fixture retained");
			}
			directoryLock.release();
		}) {
			task.set(reader.submit(() -> {
				gate.reader.set(Thread.currentThread());
				return PreparedBulkStore.read(directory, gate, config);
			}));
			assertTrue(gate.entered.await(30, TimeUnit.SECONDS),
					"the real sealed capture must reach its post-capture observation before the foreign write");
			Path log = evidence.resolve("foreign-writer.log");
			Path childTmp = evidence.resolve("foreign-tmp");
			Files.createDirectory(childTmp);
			Process started = new ProcessBuilder(Path.of(System.getProperty("java.home"), "bin", "java").toString(),
					"--enable-native-access=ALL-UNNAMED", "-ea", "-Djava.io.tmpdir=" + childTmp,
					"-cp", System.getProperty("java.class.path"), ForeignWriter.class.getName(),
					directory.toString(), Base64.getEncoder().encodeToString(replacement))
							.redirectErrorStream(true)
							.redirectOutput(log.toFile())
							.start();
			child.set(started);
			childSettled.set(false);
			assertTrue(child.get().waitFor(30, TimeUnit.SECONDS),
					() -> "foreign writer did not settle; retained pid=" + child.get().pid() + " log=" + log);
			childSettled.set(true);
			assertEquals(0, child.get().exitValue(), "foreign writer failed; retained log: " + log);
			assertTrue(Files.readString(log).contains("FOREIGN_GENERATION_COMMITTED"));
			long afterTransaction = LmdbCompatibilityFixtures.nativeTransactionId(directory);
			assertTrue(afterTransaction > beforeTransaction, "the independent native writer must commit");
			assertArrayEquals(replacement, LmdbCompatibilityFixtures.nativeGet(directory, "gc_meta",
					ReferenceCountProof.GENERATION_KEY));
			gate.release.countDown();
			assertNull(task.get().get(30, TimeUnit.SECONDS),
					"fallback must not admit the pre-commit clean snapshot as current");
		}

		LmdbStore reopened = new LmdbStore(directory.toFile(), config);
		SailRepository repository = new SailRepository(reopened);
		try {
			repository.init();
			try (var connection = repository.getConnection()) {
				assertTrue(connection.hasStatement(S, P, O, false), "the original row survives");
				assertTrue(connection.hasStatement(SECOND, P, O, false), "the later row survives");
			}
			assertTrue(!((ValueStore) reopened.getValueFactory()).hasTrustedReferenceCounts(),
					"a foreign generation must not borrow exact-count authority");
		} finally {
			repository.shutDown();
		}
	}

	private static void assertFalseBytesEqual(byte[] first, byte[] second) {
		assertNotEquals(Base64.getEncoder().encodeToString(first), Base64.getEncoder().encodeToString(second),
				"the second real close must publish different seal bytes");
	}

	private static LmdbStoreConfig config() {
		return new LmdbStoreConfig("spoc,posc").setInlineLiterals(false)
				.setForceSync(true)
				.setSketchEstimatorEnabled(false)
				.setFrontierEstimatorMode(FrontierEstimatorMode.OFF)
				.setPredicateGuaranteeIndexEnabled(true)
				.setPredicateGuaranteeIndexAutoRebuild(true);
	}

	private static void write(Path directory, LmdbStoreConfig config, boolean second) throws Exception {
		LmdbStore store = new LmdbStore(directory.toFile(), config);
		SailRepository repository = new SailRepository(store);
		try {
			repository.init();
			LmdbTestUtil.awaitPostReadyInitialization(store, 30, TimeUnit.SECONDS);
			try (var connection = repository.getConnection()) {
				connection.begin();
				connection.add(second ? SECOND : S, P, O);
				connection.commit();
			}
		} finally {
			repository.shutDown();
		}
	}

	private static final class Gate extends StoreProperties {
		final AtomicReference<Thread> reader = new AtomicReference<>();
		final AtomicBoolean armed = new AtomicBoolean(true);
		final CountDownLatch entered = new CountDownLatch(1);
		final CountDownLatch release = new CountDownLatch(1);

		Gate(File directory) {
			super(directory);
		}

		@Override
		String getRdfTermDomainQualification() {
			String value = super.getRdfTermDomainQualification();
			boolean observationAfterSealedCapture = Thread.currentThread() == reader.get()
					&& StackWalker.getInstance().walk(frames -> {
						List<StackWalker.StackFrame> stack = frames.toList();
						return stack.stream()
								.anyMatch(
										frame -> frame.getClassName().equals(RdfTermDomainQualification.class.getName())
												&& frame.getMethodName().equals("observe"))
								&& stack.stream()
										.anyMatch(
												frame -> frame.getClassName().equals(PreparedBulkStore.class.getName())
														&& frame.getMethodName().equals("readSealed"));
					});
			if (observationAfterSealedCapture && armed.compareAndSet(true, false)) {
				entered.countDown();
				try {
					if (!release.await(30, TimeUnit.SECONDS)) {
						throw new AssertionError("prepared capture gate was not released");
					}
				} catch (InterruptedException interrupted) {
					Thread.currentThread().interrupt();
					throw new AssertionError("prepared capture gate interrupted", interrupted);
				}
			}
			return value;
		}
	}

	public static final class ForeignWriter {
		public static void main(String[] args) throws Exception {
			LmdbCompatibilityFixtures.nativePut(Path.of(args[0]), "gc_meta", ReferenceCountProof.GENERATION_KEY,
					Base64.getDecoder().decode(args[1]));
			System.out.println("FOREIGN_GENERATION_COMMITTED");
		}
	}
}
